function candidateDialog(sourceId,candidateId){const c=Sources.candidates(M.state.workspaceId,sourceId).find(c=>c.id===candidateId);if(!c)throw new Error('此更新已失效，请重新获取');const file=f(c.fileId),before=rev(file,c.headId);S.candidate=Object.assign({},c,{sourceId,candidateId});showDialog('核对来源更新','<p>'+e(file.name)+' · '+e(branch(file,c.branchId).label)+'。载入草稿后仍需核对保存。</p>'+pagedDiffTable(M.diff(before?.params||[],c.params),before?recordTitle(file,before):'原记录','来源内容')+'<p class="help-note">已有草稿需先处理。正式版本将比较原来源、当前草稿和新来源。</p>',btn('暂不处理','close-dialog')+btn('载入编辑草稿','apply-candidate','edit','primary',disabled()),true);}

function inputValue(id){return document.getElementById(id)?.value||'';}
const diffViews=new Map();let diffViewSeq=0;
function diffViewContent(view){
  const start=view.page*50,part=view.changes.slice(start,start+50);
  return diffTable(part,view.left,view.right,view.comments)+'<div class="footer"><span>共 '+view.changes.length+' 项变化 · '+(start+1)+'–'+Math.min(start+50,view.changes.length)+'</span><span class="spacer"></span>'+btn('上一页','diff-prev',null,'sm','data-view="'+view.id+'" '+(view.page?'':'disabled'))+btn('下一页','diff-next',null,'sm','data-view="'+view.id+'" '+(start+50<view.changes.length?'':'disabled'))+'</div>';
}
function pagedDiffTable(changes,left,right,comments){
  if(changes.length<=50)return diffTable(changes,left,right,comments);
  const id='diff-'+(++diffViewSeq),view={id,changes,left,right,comments,page:0};diffViews.set(id,view);
  while(diffViews.size>8)diffViews.delete(diffViews.keys().next().value);
  return '<div id="'+id+'" aria-label="逐页核对差异">'+diffViewContent(view)+'</div>';
}
function closeOverlays(){for(const id of ['dialog','drawer']){const node=document.getElementById(id);if(node.open)node.close();}}
function setContext(file,bid,rid){S.fileId=file.id;S.branchId=bid||file.branches[0].id;S.revisionId=rid||null;}
function editCount(){if(!S.edit)return;const node=document.getElementById('edit-count');if(node)node.textContent=M.diff(rev(f(S.edit.fileId),S.edit.headId)?.params||[],S.edit.params).length;}
function guardedChange(callback){if(S.edit){render();leaveDialog(callback);}else callback();}
function makeDraft(file,b,params,extra){return Object.assign({workspaceId:M.state.workspaceId,fileId:file.id,branchId:b.id,headId:b.headId,params:copy(params),message:'',links:[],linksText:''},extra||{});}
function ensureNoDraft(fileId,bid){if(S.edit||S.drafts[draftKey(fileId,bid)])throw new Error('此配置已有草稿，请先继续编辑、保存或放弃，再载入其他修改。');}
function openEditDraft(file,b,draft){setContext(file,b.id);S.edit=draft;S.allowNavigation=true;closeOverlays();go(fileUrl(file,'parameters')+'?branch='+encodeURIComponent(b.id));}
function sourceAdoption(result,fileId,bid){for(const source of Sources.list(M.state.workspaceId))for(const c of Sources.candidates(M.state.workspaceId,source.id)){if(c.fileId===fileId&&c.branchId===bid)Sources.markApplied(M.state.workspaceId,source.id,c.id,result.id);}}
async function runSource(id,opts){ensureAdmin();const wid=M.state.workspaceId,promise=Sources.run(wid,id,opts);render();const result=await promise;if(M.state.workspaceId===wid){render();toast(result.message);}return result;}
function restoreDraft(id){ensureAdmin();const file=f(),r=rev(file,id);if(!r)throw new Error('保存记录不存在');const b=branch(file,r.branchId);ensureNoDraft(file.id,b.id);openEditDraft(file,b,makeDraft(file,b,r.params,{sourceRevisionId:r.id,restoreRevisionId:r.id,message:'',operationDescription:'恢复 '+recordTitle(file,r)+' 的完整快照'}));reviewEdit();}
function newReleaseDialog(){ensureAdmin();const file=f();showDialog('新建软件版本','<label class="field"><span class="label">软件版本</span><input id="release-name" placeholder="例如：692" autofocus></label><label class="field"><span class="label">初始内容</span><select id="release-source"><option value="">稍后导入本版本文件</option>'+options(file.revisions.filter(r=>branch(file,r.branchId).kind==='baseline'&&r.kind!=='initial').slice().reverse(),'',r=>recordTitle(file,r))+'</select></label><p class="help-note">只有明确选择来源，才采用该记录作为新版本起点。未选择时保留为待初始化。</p>'+modificationFields('release'),btn('取消','close-dialog')+btn('创建版本','create-release','plus','primary'));}
